"""Binary row transfer into a schema generated by the signed Core release.

Archived SQL/DDL is never executed. The target remains inactive until a complete
import, FK validation and identity disposition succeed; interrupted imports are
restarted from the empty application tables, never merged with existing data.
"""

from __future__ import annotations

import json
import re
from collections.abc import Callable
from pathlib import Path

SCHEMA_SQL = """SELECT json_build_object(
'tables',(SELECT coalesce(json_agg(json_build_object('name',c.relname,'columns',
 (SELECT json_agg(json_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum)
 FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY c.relname),'[]'::json)
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r'),
'foreignKeys',(SELECT coalesce(json_agg(json_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname),'[]'::json)
 FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND k.contype='f'),
'sequences',(SELECT coalesce(json_agg(json_build_array(sequencename,start_value,min_value,max_value,increment_by,cycle) ORDER BY sequencename),'[]'::json) FROM pg_sequences WHERE schemaname='public'),
'migrations',(SELECT coalesce(json_agg(json_build_array(version,description,type,script,checksum,success) ORDER BY installed_rank),'[]'::json) FROM flyway_schema_history))"""

Query = Callable[[str], bytes]
Transfer = Callable[[str, Path], None]


def identifier(value: object) -> str:
    if not isinstance(value, str) or not re.fullmatch(r"[a-z_][a-z0-9_]{0,62}", value):
        raise ValueError("E_RESTORE_IDENTIFIER")
    return 'public."' + value + '"'


def file_copy_command(sql: str, path: Path) -> str:
    """psql opens explicit client files in binary mode on Windows.

    Redirected standard input can encounter CRT EOF translation for byte 0x1a.
    Only our generated table/column COPY grammar is accepted, never a PROGRAM
    or an archived SQL fragment. The private file's ACL is created by the caller.
    """
    name = r'"[a-z_][a-z0-9_]{0,62}"'
    match = re.fullmatch(
        r"COPY (public\."
        + name
        + r" \("
        + name
        + r"(?:,"
        + name
        + r")*\)) (TO STDOUT|FROM STDIN) \(FORMAT binary\)",
        sql,
    )
    filename = path.resolve().as_posix()
    if match is None or any(ord(ch) < 32 for ch in filename):
        raise ValueError("E_RESTORE_COPY_FILE")
    from host import reject_links

    reject_links(path)
    return (
        "\\copy "
        + match[1]
        + (" TO '" if match[2] == "TO STDOUT" else " FROM '")
        + filename.replace("'", "''")
        + "' (FORMAT binary)"
    )


def descriptor(raw: bytes) -> dict:
    if len(raw) > 4 * 1024**2:
        raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    from bundle import unique_object

    value = json.loads(raw, object_pairs_hook=unique_object)
    if not isinstance(value, dict) or set(value) != {
        "tables",
        "foreignKeys",
        "sequences",
        "migrations",
    }:
        raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    for name, maximum in (
        ("tables", 256),
        ("foreignKeys", 2048),
        ("sequences", 256),
        ("migrations", 256),
    ):
        if not isinstance(value[name], list) or len(value[name]) > maximum:
            raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    names = []
    for table in value["tables"]:
        if (
            not isinstance(table, dict)
            or set(table) != {"name", "columns"}
            or not isinstance(table["columns"], list)
            or not 1 <= len(table["columns"]) <= 1024
        ):
            raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
        identifier(table["name"])
        names.append(table["name"])
        columns = []
        for column in table["columns"]:
            if not isinstance(column, list) or len(column) != 6:
                raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
            identifier(column[0])
            columns.append(column[0])
            if (
                not isinstance(column[1], str)
                or type(column[2]) is not bool
                or not isinstance(column[3], str)
                or column[3] not in {"", "a", "d"}
                or not isinstance(column[4], str)
                or column[4] not in {"", "s", "v"}
                or column[5] is not None
                and not isinstance(column[5], str)
            ):
                raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
        if len(columns) != len(set(columns)):
            raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    if (
        names != sorted(set(names))
        or "flyway_schema_history" not in names
        or len(names) < 2
    ):
        raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    sequences = []
    for sequence in value["sequences"]:
        if (
            not isinstance(sequence, list)
            or len(sequence) != 6
            or any(type(number) is not int for number in sequence[1:5])
            or type(sequence[5]) is not bool
        ):
            raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
        identifier(sequence[0])
        sequences.append(sequence[0])
    if sequences != sorted(set(sequences)):
        raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
    for key in value["foreignKeys"]:
        if (
            not isinstance(key, dict)
            or set(key) != {"table", "name", "definition"}
            or key["table"] not in names
            or not isinstance(key["definition"], str)
            or len(key["definition"]) > 8192
        ):
            raise ValueError("E_RESTORE_SCHEMA_DESCRIPTOR")
        identifier(key["name"])
    return value


def capture(
    query: Query, export: Transfer, directory: Path
) -> tuple[dict, dict[str, Path]]:
    schema = descriptor(query(SCHEMA_SQL))
    directory.mkdir()
    files = {}
    for number, table in enumerate(schema["tables"]):
        if table["name"] == "flyway_schema_history":
            continue
        columns = ",".join(
            '"' + item[0] + '"' for item in table["columns"] if not item[4]
        )
        path = directory / (f"{number:04d}.copy")
        export(
            "COPY "
            + identifier(table["name"])
            + " ("
            + columns
            + ") TO STDOUT (FORMAT binary)",
            path,
        )
        files["database-data/" + path.name] = path
    positions = {}
    for sequence in schema["sequences"]:
        row = json.loads(
            query(
                "SELECT json_build_array(last_value,is_called) FROM "
                + identifier(sequence[0])
            )
        )
        if (
            not isinstance(row, list)
            or len(row) != 2
            or type(row[0]) is not int
            or not -(2**63) <= row[0] < 2**63
            or type(row[1]) is not bool
        ):
            raise ValueError("E_RESTORE_SEQUENCE")
        positions[sequence[0]] = row
    return {"formatVersion": 1, "schema": schema, "sequencePositions": positions}, files


def restore(
    query: Query,
    execute: Callable[[str], None],
    copy_in: Transfer,
    snapshot: dict,
    files: dict[str, Path],
) -> None:
    if (
        not isinstance(snapshot, dict)
        or set(snapshot) != {"formatVersion", "schema", "sequencePositions"}
        or type(snapshot["formatVersion"]) is not int
        or snapshot["formatVersion"] != 1
    ):
        raise ValueError("E_RESTORE_PORTABLE_DATA_REQUIRED")
    archived = descriptor(json.dumps(snapshot["schema"]).encode())
    trusted = descriptor(query(SCHEMA_SQL))
    if json.dumps(archived, sort_keys=True) != json.dumps(trusted, sort_keys=True):
        raise ValueError("E_RESTORE_SCHEMA_MISMATCH")
    expected = {
        f"database-data/{number:04d}.copy"
        for number, table in enumerate(trusted["tables"])
        if table["name"] != "flyway_schema_history"
    }
    if (
        set(files) != expected
        or not isinstance(snapshot["sequencePositions"], dict)
        or set(snapshot["sequencePositions"])
        != {row[0] for row in trusted["sequences"]}
    ):
        raise ValueError("E_RESTORE_PORTABLE_DATA_REQUIRED")
    for row in snapshot["sequencePositions"].values():
        if (
            not isinstance(row, list)
            or len(row) != 2
            or type(row[0]) is not int
            or not -(2**63) <= row[0] < 2**63
            or type(row[1]) is not bool
        ):
            raise ValueError("E_RESTORE_SEQUENCE")
    tables = [
        identifier(table["name"])
        for table in trusted["tables"]
        if table["name"] != "flyway_schema_history"
    ]
    # Only fresh owned restore targets reach this adapter. No archived SQL is
    # interpolated: names/DDL below come from the fresh signed target schema.
    execute("TRUNCATE " + ",".join(tables) + " RESTART IDENTITY CASCADE")
    for number, table in enumerate(trusted["tables"]):
        if table["name"] == "flyway_schema_history":
            continue
        columns = ",".join(
            '"' + item[0] + '"' for item in table["columns"] if not item[4]
        )
        execute("ALTER TABLE " + identifier(table["name"]) + " DISABLE TRIGGER ALL")
        try:
            copy_in(
                "COPY "
                + identifier(table["name"])
                + " ("
                + columns
                + ") FROM STDIN (FORMAT binary)",
                files[f"database-data/{number:04d}.copy"],
            )
        finally:
            execute("ALTER TABLE " + identifier(table["name"]) + " ENABLE TRIGGER ALL")
    for key in trusted["foreignKeys"]:
        # Recreate the trusted FK as NOT VALID, forcing an actual scan after
        # bulk COPY (VALIDATE on an already-valid constraint would skip it).
        name = '"' + key["name"] + '"'
        execute(
            "BEGIN; ALTER TABLE "
            + identifier(key["table"])
            + " DROP CONSTRAINT "
            + name
            + "; ALTER TABLE "
            + identifier(key["table"])
            + " ADD CONSTRAINT "
            + name
            + " "
            + key["definition"].removesuffix(" NOT VALID")
            + " NOT VALID; ALTER TABLE "
            + identifier(key["table"])
            + " VALIDATE CONSTRAINT "
            + name
            + "; COMMIT"
        )
    for name, (position, called) in snapshot["sequencePositions"].items():
        identifier(name)
        execute(
            "SELECT setval('public.\""
            + name
            + "\"',"
            + str(position)
            + ","
            + ("true" if called else "false")
            + ")"
        )
